import { Component, OnDestroy, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AlertController, LoadingController } from '@ionic/angular';
import { Subscription } from 'rxjs';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { VehicleProfile, VehicleProfileStore } from '../vehicle-profile/vehicle-profile.store';

interface LabField { key: string; label: string; unit: string; value: number; min: number; max: number; step: number; info: string; }
interface LabResult { label: string; value: string; unit?: string; tone?: 'success' | 'warning' | 'danger' | 'primary'; }
interface LabTool { slug: string; title: string; subtitle: string; icon: string; accent: string; fields: LabField[]; note: string; }

@Component({
  selector: 'app-boost-control',
  templateUrl: './boost-control.component.html',
  styleUrls: ['./boost-control.component.scss']
})
export class BoostControlComponent implements OnInit, OnDestroy {
  readonly tool: LabTool = { slug: 'boost-control', title: 'مهندسی Boost Control', subtitle: 'فنر ویست‌گیت، Duty اولیه و حاشیه کنترل', icon: 'speedometer-outline', accent: '#ef4444', note: 'Duty خروجی نقطه‌ی شروع محافظه‌کارانه برای تیون روی داینو است.', fields: [
      this.f('spring', 'فشار فنر ویست‌گیت', 'bar', .6, .1, 3, .05, 'بوست مکانیکی با Duty صفر.'), this.f('target', 'بوست هدف', 'bar', 1.2, .1, 4, .05, 'فشار بوست درخواستی.'),
      this.f('gain', 'توان مؤثر شیر کنترل', '%', 80, 10, 150, 1, 'اثرگذاری سیستم سلونوئید و شیلنگ‌ها.'), this.f('backpressure', 'نسبت فشار اگزوز به بوست', ':1', 1.6, .5, 5, .1, 'نسبت EMAP به MAP که روی بازشدن ویست‌گیت اثر دارد.') ] };
  isShow = false;
  isCheck = true;
  profiles: VehicleProfile[] = [];
  selectedProfileId = '';
  profileNotice = '';
  private loadedProfileUpdatedAt = '';
  form: FormGroup;
  results: LabResult[] = [];
  advice = '';
  csvName = '';
  csvRows = 0;
  private readonly subscription = new Subscription();

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private alerts: AlertController,
    public loadingController: LoadingController,
    private courseService: CourseService,
    private siteService: SliderService
  ) {}

  ngOnInit(): void {
    this.buildForm();
    void this.check();
  }

  ngOnDestroy(): void { this.subscription.unsubscribe(); }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(43).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;
                              this.isShow = true;
                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
              this.isShow = true;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ionViewWillEnter(): void {
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active && this.form && (active.id !== this.selectedProfileId ||
      active.updatedAt !== this.loadedProfileUpdatedAt)) {
      this.applyProfile(active.id);
    }
  }

  applyProfile(id: string): void {
    const profile = this.profiles.find(item => item.id === id);
    if (!profile || !this.form) { return; }
    const values = VehicleProfileStore.toolValues(profile, this.tool.slug);
    const valid: Record<string, number> = {};
    Object.keys(values).forEach(key => {
      const field = this.tool.fields.find(item => item.key === key);
      if (field && values[key] >= field.min && values[key] <= field.max) { valid[key] = values[key]; }
    });
    this.form.patchValue(valid);
    this.profileNotice = `${Object.keys(valid).length} مقدار از ${this.tool.fields.length} ورودی از پروفایل اعمال شد؛ باقی مقادیر پیش‌فرض ابزارند.`;
    this.selectedProfileId = id;
    this.loadedProfileUpdatedAt = profile.updatedAt;
    try { VehicleProfileStore.select(id); } catch { /* Calculation still works if storage is blocked. */ }
    this.calculate();
  }

  private f(key: string, label: string, unit: string, value: number, min: number, max: number, step: number, info: string): LabField {
    return { key, label, unit, value, min, max, step, info };
  }

  private buildForm(): void {
    const controls = {};
    this.tool.fields.forEach(field => controls[field.key] = [field.value, [Validators.required, Validators.min(field.min), Validators.max(field.max)]]);
    this.form = this.fb.group(controls);
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active) { this.applyProfile(active.id); }

    this.subscription.add(this.form.valueChanges.subscribe(() => {
      this.calculate();
    }));
    this.calculate();
  }

  reset(): void {
    const values = {};
    this.tool.fields.forEach(field => values[field.key] = field.value);
    this.form.reset(values);
    this.csvName = '';
    this.csvRows = 0;
    this.calculate();
  }

  async onInfo(field: LabField): Promise<void> {
    const alert = await this.alerts.create({ cssClass: 'tuner-plus-beta-alert', header: field.label, message: field.info, buttons: ['متوجه شدم'] });
    await alert.present();
  }

  private r(label: string, value: number | string, unit = '', tone: LabResult['tone'] = 'primary'): LabResult {
    return { label, value: typeof value === 'number' ? this.round(value).toLocaleString('fa-IR') : value, unit, tone };
  }

  private round(value: number): number { return Math.round(value * 100) / 100; }

  calculate(): void {
    if (!this.form || this.form.invalid) { this.results = []; return; }
    const v = this.form.getRawValue();
    const n = (key: string) => Number(v[key]);
    let r: LabResult[] = [];
    let advice = '';
    const ratio = n('target') / n('spring'); const duty = Math.max(0, Math.min(90, ((ratio - 1) / (n('gain') / 100)) * 42 + Math.max(0, n('backpressure') - 1) * 5)); const margin = (n('target') - n('spring')) / n('target') * 100; r = [this.r('Duty اولیه محافظه‌کارانه', duty, '%', duty < 75 ? 'success' : 'warning'), this.r('نسبت هدف به فنر', ratio, ':1'), this.r('دامنه کنترل', margin, '%')]; advice = ratio > 2.5 ? 'فنر ویست‌گیت برای این هدف بسیار سبک است؛ کنترل ناپایدار محتمل است.' : 'تیون را از Duty کمتر آغاز و با لاگ بوست پله‌ای افزایش دهید.';
    this.results = r;
    this.advice = advice;
  }
}
